# Generated by scripts/update-homebrew.py. Edit scripts/aigc.rb.in instead.
class Aigc < Formula
  desc "Local garbage collector for development storage on macOS"
  homepage "https://github.com/MyhreS/AI-Garbage-Collector"
  version "0.3.0"
  license "MIT"

  depends_on macos: :ventura

  on_macos do
    on_arm do
      url "https://github.com/MyhreS/AI-Garbage-Collector/releases/download/v0.3.0/aigc-aarch64-apple-darwin.tar.gz"
      sha256 "5a999853d170b4731ba5b0dfbfcf2848b3387a2f5d62945c557867ac28f8790d"
    end

    on_intel do
      url "https://github.com/MyhreS/AI-Garbage-Collector/releases/download/v0.3.0/aigc-x86_64-apple-darwin.tar.gz"
      sha256 "4435d91053b93e82f17950950660624f29eb4c4956563dc1bbebbac4f37f5522"
    end
  end

  def install
    bin.install "aigc"
    doc.install "README.md"
    doc.install "docs" if Dir.exist?("docs")
  end

  service do
    name macos: "io.aigc.collector"
    run [opt_bin/"aigc", "collect"]
    run_type :interval
    interval 3600
    run_at_load true
    working_dir Dir.home
    environment_variables HOME: Dir.home,
                          PATH: "#{Dir.home}/.local/bin:#{Dir.home}/.docker/bin:/usr/local/bin:#{std_service_path_env}"
  end

  def caveats
    <<~EOS
      A direct brew install does not start cleanup. To start the hourly collector:
        brew services start myhres/aigc/aigc

      For one-command installation and automatic startup, use the Brewfile:
        curl -fsSL https://raw.githubusercontent.com/MyhreS/AI-Garbage-Collector/main/Brewfile | brew bundle --file=-

      Inspect resources with:
        aigc status

      If switching from the standalone installer, stop its service first:
        aigc service uninstall
      Then use brew services to manage the collector. Do not use sudo.
    EOS
  end
end
